using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync,
        "web_search", "Search the web for information on a topic. Returns a list of result snippets."),
    AIFunctionFactory.Create(notebook.SaveNote,
        "save_note", "Save a research note with a title and body for later reference."),
    AIFunctionFactory.Create(notebook.GetNotes,
        "get_notes", "Retrieve all saved research notes."),
};

// ---------------------------------------------------------------------------
// Agent setup
// ---------------------------------------------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

agent.Instructions = """
    You are a research agent. When given a topic you MUST:
    1. Use the web_search tool multiple times with different queries to gather broad information.
    2. Use the save_note tool to record key findings as you go.
    3. After gathering enough information (at least 3 searches), use get_notes to review your notes.
    4. Produce a well-structured summary with sections and references.
    Always search before answering. Never fabricate facts.
    """;

// ---------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync(conversationId: Guid.NewGuid().ToString());

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
    Tools = [.. tools],
});

var result = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine("─── Research Summary ───────────────────────────────────");
Console.WriteLine(result.Text);
Console.WriteLine("────────────────────────────────────────────────────────");

if (notebook.Notes.Count > 0)
{
    Console.WriteLine($"\n📝 {notebook.Notes.Count} note(s) taken during research:");
    foreach (var note in notebook.Notes)
    {
        Console.WriteLine($"  • {note.Title}");
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// Tool implementations
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>Simulated web search tool that uses Bing search via HTTP.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(
        [Description("The search query")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo instant-answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            Http.DefaultRequestHeaders.UserAgent.Clear();
            Http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

            var json = await Http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract
            var abs = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abs}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                    {
                        var t = text.GetString();
                        if (!string.IsNullOrWhiteSpace(t))
                            results.Add(t);
                    }
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a more specific query.";

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Note-taking tool that stores research findings in memory.</summary>
sealed class Notebook
{
    public List<Note> Notes { get; } = [];

    public string SaveNote(
        [Description("Short title for this note")] string title,
        [Description("The note content / findings")] string body)
    {
        Notes.Add(new Note(title, body));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note '{title}' saved successfully. You now have {Notes.Count} note(s).";
    }

    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", Notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Body}"));
    }
}

record Note(string Title, string Body);

