 /// <summary>Simulated web search tool that uses DuckDuckGo instant-answer API.</summary>
 static class WebSearchTool
 {
     private static readonly HttpClient Http = new();

     public static async Task<string> SearchAsync(
         [Description("The search query")] string query,
         CancellationToken cancellationToken = default)
     {
         Console.WriteLine($"  🔍 Searching: \"{query}\"");

         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

             Http.DefaultRequestHeaders.UserAgent.Clear();
             Http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

             var json = await Http.GetStringAsync(url, cancellationToken);
             using var doc = JsonDocument.Parse(json);
             var root = doc.RootElement;

             var results = new List<string>();

             // Abstract
             var abs = root.GetProperty("Abstract").GetString();
             if (!string.IsNullOrWhiteSpace(abs))
             {
                 var source = root.GetProperty("AbstractSource").GetString();
                 results.Add($"[{source}] {abs}");
             }

             // Related topics
             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var item in topics.EnumerateArray().Take(5))
                 {
                     if (item.TryGetProperty("Text", out var text))
                     {
                         var t = text.GetString();
                         if (!string.IsNullOrWhiteSpace(t))
                             results.Add(t);
                     }
                 }
             }

             if (results.Count == 0)
                 return $"No detailed results found for '{query}'. Try a more specific query.";

             return string.Join("\n\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }
 }

